WITH base AS (SELECT wz.*,w.moisture_score FROM public.weather_zones wz JOIN public.weather_observations w ON w.weather_zone_id=wz.weather_sample_id AND w.obs_date='2026-10-24' WHERE wz.is_active),scores AS (SELECT b.id,b.center_lat,s.name_sv,variant, greatest(0,least(1,(0.45*exp(-power((m-h.moisture_optimum)/h.moisture_tolerance,2))+0.30*exp(-power((coalesce(b.forest_share,b.forest_cover)-h.forest_optimum)/h.forest_tolerance,2))+0.25*(CASE WHEN coalesce(b.vol_spruce,0)+coalesce(b.vol_pine,0)+coalesce(b.vol_birch,0)<5 THEN 0.5 ELSE (h.aff_spruce*coalesce(b.vol_spruce,0)+h.aff_pine*coalesce(b.vol_pine,0)+h.aff_birch*coalesce(b.vol_birch,0))/(coalesce(b.vol_spruce,0)+coalesce(b.vol_pine,0)+coalesce(b.vol_birch,0)) END))*CASE WHEN s.season_start IS NULL OR s.season_end IS NULL THEN 1 WHEN extract(doy from s.season_start)<=extract(doy from s.season_end) THEN CASE WHEN extract(doy from date '2026-10-24') BETWEEN extract(doy from s.season_start) AND extract(doy from s.season_end) THEN 1 ELSE 0.65 END ELSE CASE WHEN extract(doy from date '2026-10-24')>=extract(doy from s.season_start) OR extract(doy from date '2026-10-24')<=extract(doy from s.season_end) THEN 1 ELSE 0.65 END END)) score FROM base b CROSS JOIN public.species s JOIN public.species_habitat_profiles h ON h.species_id=s.id CROSS JOIN LATERAL (VALUES ('current',CASE WHEN b.soil_wetness IS NULL THEN coalesce(b.moisture_score,0) ELSE 0.6*coalesce(b.moisture_score,0)+0.4*b.soil_wetness END),('land',CASE WHEN b.soil_wetness_land IS NULL THEN coalesce(b.moisture_score,0) ELSE 0.6*coalesce(b.moisture_score,0)+0.4*b.soil_wetness_land END)) q(variant,m)) SELECT name_sv,variant,floor(center_lat) latitude,count(*) n,avg(score) mean FROM scores GROUP BY name_sv,variant,floor(center_lat) ORDER BY name_sv,latitude,variant